window.RTLBenchLSData.register("assets/d3c80d235a5a2f20bb4d10dcc611214bb0541af023ed42b5c63746ea7869b32e.txt","module rtlpp_04057 (\n    input wire clk,\n    input wire reset,\n    input wire [1:0] select,\n    input wire [3:0] in0,\n    input wire [3:0] in1,\n    input wire [3:0] in2,\n    input wire [3:0] in3,\n    input wire in0_valid,\n    input wire in1_valid,\n    input wire in2_valid,\n    input wire in3_valid,\n    output reg [3:0] out_b,\n    output reg out_valid_b\n);\n\nreg [3:0] out_1_mux, out_2_mux;\nreg valid_1_mux, valid_2_mux;\n\n// Internal 2:1 MUX\nalways @(*) begin\n    if (reset) begin\n        out_1_mux = 4'b0;\n        valid_1_mux = 1'b0;\n    end else begin\n        if (select[0] == 1'b0) begin\n            out_1_mux = in0;\n            valid_1_mux = in0_valid;\n        end else begin\n            out_1_mux = in1;\n            valid_1_mux = in1_valid;\n        end\n    end\nend\n\nalways @(*) begin\n    if (reset) begin\n        out_2_mux = 4'b0;\n        valid_2_mux = 1'b0;\n    end else begin\n        if (select[0] == 1'b0) begin\n            out_2_mux = in2;\n            valid_2_mux = in2_valid;\n        end else begin\n            out_2_mux = in3;\n            valid_2_mux = in3_valid;\n        end\n    end\nend\n\nalways @(*) begin\n    if (reset) begin\n        out_b = 4'b0;\n        out_valid_b = 1'b0;\n    end else begin\n        if (select[1] == 1'b0) begin\n            out_b = out_1_mux;\n            out_valid_b = valid_1_mux;\n        end else begin\n            out_b = out_2_mux;\n            out_valid_b = valid_2_mux;\n        end\n    end\nend\n\nendmodule");
